## Building a Calendar Helper

### Days Per Month

```xiom
fn days_in_month(month: Int, year: Int) -> Int {
  if month == 2 {
    if is_leap_year(year) { return 29; };
    return 28;
  };
  if month == 4 || month == 6 || month == 9 || month == 11 {
    return 30;
  };
  31
}

fn is_leap_year(year: Int) -> Bool {
  if year % 400 == 0 { return true; };
  if year % 100 == 0 { return false; };
  year % 4 == 0
}
```

### Day of Week (Zeller's Algorithm)

```xiom
fn day_of_week(day: Int, month: Int, year: Int) -> Int {
  let m = month;
  let y = year;
  if m < 3 {
    m += 12;
    y -= 1;
  };
  let k = y % 100;
  let j = y / 100;
  let h = (day + (13 * (m + 1)) / 5 + k + k / 4 + j / 4 - 2 * j) % 7;

  let result = ((h % 7) + 7) % 7;
  result
}
```

Result: 0=Saturday, 1=Sunday, 2=Monday, ..., 6=Friday.

### Day Name

```xiom
fn day_name(dow: Int) -> Str {
  if dow == 0 { return "Saturday"; };
  if dow == 1 { return "Sunday"; };
  if dow == 2 { return "Monday"; };
  if dow == 3 { return "Tuesday"; };
  if dow == 4 { return "Wednesday"; };
  if dow == 5 { return "Thursday"; };
  "Friday"
}
```

### Days Between Dates

```xiom
fn days_between(d1: Int, m1: Int, y1: Int, d2: Int, m2: Int, y2: Int) -> Int {
  let days1 = day_of_year(d1, m1, y1) + days_before_year(y1);
  let days2 = day_of_year(d2, m2, y2) + days_before_year(y2);
  days2 - days1
}
```

